import React from 'react';

const images = [
  "/assets/images/references/24.png",
  "/assets/images/references/25.png",
  "/assets/images/references/26.png",
  "/assets/images/references/27.png",
  "/assets/images/references/1.png",
  "/assets/images/references/2.png",
  "/assets/images/references/3.png",
  "/assets/images/references/4.png",
  "/assets/images/references/5.png",
  "/assets/images/references/6.png",
  "/assets/images/references/7.png",
  "/assets/images/references/8.png",
  "/assets/images/references/9.png",
  "/assets/images/references/10.png",
  "/assets/images/references/11.png",
  "/assets/images/references/12.png",
  "/assets/images/references/13.png",
  "/assets/images/references/14.png",
  "/assets/images/references/15.png",
  "/assets/images/references/16.png",
];

function Carousel() {
  return (
    <div className="carousel-container">
      <div className="slick-slider slick-initialized" dir="ltr">
        <button type="button" data-role="none" className="slick-arrow slick-prev" style={{ display: 'block' }}>
          Previous
        </button>
        <div className="slick-list">
          <div className="slick-track" style={{ width: '11136px', opacity: 1 }}>
            {images.map((src, index) => (
              <div key={index} data-index={index} className="slick-slide" style={{ width: '192px' }}>
                <div>
                  <div className="image-wrapper">
                    <img
                      alt={`reference ${index}`}
                      data-test="reference-image"
                      loading="lazy"
                      width="172"
                      height="100"
                      className="reference-image"
                      src={src}
                    />
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
        <button type="button" data-role="none" className="slick-arrow slick-next" style={{ display: 'block' }}>
          Next
        </button>
      </div>

      <style jsx>{`
        .carousel-container {
          position: relative;
          max-width: 100%;
        }

        .slick-slider {
          display: flex;
          align-items: center;
          justify-content: center;
          position: relative;
          overflow: hidden;
        }

        .slick-arrow {
          background-color: rgba(0, 0, 0, 0.5);
          color: white;
          border: none;
          font-size: 16px;
          padding: 10px;
          cursor: pointer;
        }

        .slick-prev {
          left: 10px;
          position: absolute;
        }

        .slick-next {
          right: 10px;
          position: absolute;
        }

        .slick-list {
          display: flex;
          flex-wrap: nowrap;
          overflow: hidden;
        }

        .slick-track {
          display: flex;
          transition: transform 0.3s ease;
        }

        .slick-slide {
          flex: 0 0 auto;
          margin-right: 10px;
          transition: opacity 0.5s ease;
        }

        .image-wrapper {
          width: 100%;
          display: inline-block;
        }

        .reference-image {
          width: 100%;
          height: auto;
          object-fit: contain;
        }
      `}</style>
    </div>
  );
}

export default Carousel;
